-- 0110: heavy-item freight groundwork (owner rule, Aug 2026).
-- A 17.8 kg pedestal fan cost Rs 1,800 extra to ship; units over 10 kg now
-- carry a flat Rs 1,000 per-unit freight fee (lib/pricing HEAVY_FREIGHT_FEE).
-- ship_weight_kg backfilled from brand spec sheets (642 products) plus
-- conservative class heuristics (127: pedestal/wall fans 450mm+ ~12kg,
-- storage geysers 15L+ ~13kg, submersible/openwell pumps ~20kg, monoblocks
-- 1HP+ ~14kg). Editable per product in the admin console; only fills NULLs,
-- so hand-set values are never overwritten. Idempotent.

alter table public.products add column if not exists ship_weight_kg numeric;

update public.products set ship_weight_kg = 20 where id = 'cro-3w10ak1a' and ship_weight_kg is null;
